description:
{
  "image_category": "SIGN_ILLUSTRATION",
  "summary": "Hình ảnh minh họa 5 biến thể của biển số W.205 (a, b, c, d, e) thuộc nhóm biển báo 'Đường giao nhau' theo QCVN 41:2024/BGTVT, dùng để báo trước nơi giao nhau cùng mức của các tuyến đường cùng cấp.",
  "items": [
    {
      "identifier": "Biển số W.205(a)",
      "visual_or_geometric_features": "Hình tam giác đều, viền đỏ, nền vàng, biểu tượng: dấu cộng (+) màu đen ở trung tâm",
      "meaning_or_specification": "Biển báo trước sắp đến nơi giao nhau cùng mức của các tuyến đường cùng cấp (không có đường nào ưu tiên), dạng giao nhau hình chữ thập."
    },
    {
      "identifier": "Biển số W.205(b)",
      "visual_or_geometric_features": "Hình tam giác đều, viền đỏ, nền vàng, biểu tượng: hình chữ T ngược (┴) màu đen ở trung tâm",
      "meaning_or_specification": "Biển báo trước sắp đến nơi giao nhau cùng mức, dạng giao nhau hình chữ T ngược (đường ngang cắt đường dọc từ phía trên)."
    },
    {
      "identifier": "Biển số W.205(c)",
      "visual_or_geometric_features": "Hình tam giác đều, viền đỏ, nền vàng, biểu tượng: hình chữ T (┬) màu đen ở trung tâm",
      "meaning_or_specification": "Biển báo trước sắp đến nơi giao nhau cùng mức, dạng giao nhau hình chữ T (đường ngang cắt đường dọc từ phía dưới)."
    },
    {
      "identifier": "Biển số W.205(d)",
      "visual_or_geometric_features": "Hình tam giác đều, viền đỏ, nền vàng, biểu tượng: hình chữ T (┴) nhưng đường ngang nằm trên đường dọc (T) màu đen ở trung tâm",
      "meaning_or_specification": "Biển báo trước sắp đến nơi giao nhau cùng mức, dạng giao nhau hình chữ T với đường ngang nằm trên đường dọc (tương tự W.205(b) nhưng trình bày khác)."
    },
    {
      "identifier": "Biển số W.205(e)",
      "visual_or_geometric_features": "Hình tam giác đều, viền đỏ, nền vàng, biểu tượng: hình chữ Y màu đen ở trung tâm",
      "meaning_or_specification": "Biển báo trước sắp đến nơi giao nhau cùng mức, dạng giao nhau hình chữ Y (ba đường hợp thành hình Y)."
    }
  ]
}
